EXTRAS = [
dict(n=61, gr='pastbe', vb='be,go,stay,visit,swim',
 c1="Was e were|Was é para I, he, she, it. Were é para you, we, they. 'There was' e 'there were' seguem o substantivo que vem depois. Em perguntas: 'Where were you last night?'.",
 c2="Praias famosas|Praias como Copacabana e Bondi (Austrália) são famosas no mundo inteiro. Em inglês, 'beach' é praia, 'sand' é areia e 'seashore' é beira-mar. 'Seaside' no Reino Unido é a cidade litorânea.",
 ar=("A weekend away","Last weekend, Finn and his family were at the beach. The weather was sunny and the water was warm. There were not many people. They were happy and relaxed. They built sandcastles, swam in the sea and ate ice cream. On Sunday, the weather was cloudy, but they were still glad to be there. In the evening, they walked on the sand and watched the sunset. Finn says, \"It was the best weekend of the year.\" His little sister says, \"Let's go again next month!\"","Finn e a família passam um fim de semana ensolarado na praia.","Como estava o tempo no sábado?=Sunny|Rainy|Snowy;;O que fizeram na praia?=Built sandcastles|Played tennis|Went shopping"),
 ex="I was over the moon.=Eu estava nas nuvens.~Muito feliz|It was a blast!=Foi demais!~Diversão|We had a great time.=Nos divertimos muito.~Diversão|It was a nightmare.=Foi um pesadelo.~Experiência ruim|You should have been there!=Você devia ter ido!~Convite perdido",
 tf="Was é passado de is.=T|Were é usado com I.=F|O tempo estava ensolarado no sábado.=T|Finn foi à praia sozinho.=F",
 odd="was,were,be,table=table|beach,sand,sea,coat=coat"),
dict(n=62, gr='pastreg', vb='cook,clean,watch,visit,call',
 c1="A pronúncia do -ed|O -ed soa /t/ depois de sons surdos (worked), /d/ depois de sons sonoros (played) e /ɪd/ depois de t ou d (wanted). Não pronuncie sempre 'êd'!",
 c2="Verbos no passado|Quase 70% dos verbos mais usados em inglês são irregulares, mas os regulares são infinitos! Para formar o passado, basta -ed: walk → walked, play → played, clean → cleaned.",
 ar=("A busy Sunday","Last Sunday, Tao cleaned his apartment in the morning. At noon he cooked noodles with his sister. In the afternoon they walked in the park and visited their grandmother. She baked cookies and they listened to old music. At night they watched an old movie and talked until eleven. Tao was tired but happy. \"A perfect Sunday,\" he said. His sister smiled. \"We should do it every week.\" Tao agreed. Family time is the best time.","Domingo cheio: limpeza, almoço, passeio e visita à avó.","O que Tao cozinhou?=Noodles|Pizza|Cake;;Quem eles visitaram?=Their grandmother|A friend|A teacher"),
 ex="What have you been up to?=O que você tem feito?~Reencontro|I stayed in.=Fiquei em casa.~Fim de semana|I caught up with friends.=Me reuni com amigos.~Lazer|It was nothing special.=Não foi nada demais.~Resposta|I kept busy.=Me mantive ocupado.~Ocupação",
 tf="Cooked é o passado de cook.=T|Visited é presente.=F|Tao limpou o apartamento.=T|Tao assistiu a um filme à noite.=T",
 odd="cleaned,cooked,walked,go=go|yesterday,last night,last week,tomorrow=tomorrow"),
dict(n=63, gr='pastirr', vb='go,see,buy,eat,have',
 c1="Irregulares que você já usa|Você usa irregulares o tempo todo: was, had, went, did, said, got, made, saw. Os 20 mais comuns representam mais de 60% de todos os verbos no passado.",
 c2="Mercados do mundo|Mercados como Borough Market (Londres) e Pike Place (Seattle) são famosos. Neles você vê peixes, frutas e queijos. 'Stall' é a barraca e 'vendor' é o vendedor.",
 ar=("At the market yesterday","Yesterday Pablo went to the market. He saw many things: red apples, big fish, colorful hats and old books. He bought apples and a fish. He ate a sandwich and drank coffee at a small stall. Then he met Mia. She gave him a book about cooking. \"I found it at a second-hand stall,\" she said. Pablo got home at six and cooked fish with rice using a recipe from the book. His family ate every bit. It was a wonderful day.","Pablo volta do mercado com compras e um livro de presente.","O que Pablo bebeu?=Coffee|Tea|Juice;;Quem lhe deu o livro?=Mia|Omar|Ana"),
 ex="I went for it.=Eu fui em frente.~Decisão|It slipped my mind.=Me escapou da cabeça.~Esquecer|I had a blast.=Foi muito divertido.~Diversão|I got it!=Entendi!~Entender|I saw it coming.=Já esperava.~Previsão",
 tf="Went é passado de go.=T|Bought é passado de buy.=T|Pablo comprou um livro.=F|Mia deu um livro a Pablo.=T",
 odd="went,saw,bought,go=go|market,stall,fish,slept=slept"),
dict(n=64, gr='pastirr', vb='read,write,speak,say,find',
 c1="Read no passado|'Read' no passado se escreve igual, mas se pronuncia /rɛd/ (como 'red'). Só pelo contexto sabemos se é presente ou passado: 'I read every day' x 'I read it yesterday'.",
 c2="Clubes do livro|Os 'book clubs' são muito populares nos países de língua inglesa. Cada mês o grupo lê um livro e depois discute. Muita gente aprende inglês lendo graded readers (livros simplificados).",
 ar=("The book club","Vera belongs to a book club. Last month they read a mystery novel. Vera finished it in three days. She wrote a review and met the author at the library. \"What did you think of the ending?\" the author asked. \"I thought it was wonderful,\" said Vera. The author told her a secret about the next book. Everybody in the club wanted to know it, but Vera said, \"I promised not to tell!\" They all laughed. At the next meeting, they chose a new book.","Vera lê um mistério, escreve uma resenha e guarda um segredo.","Quantos dias Vera levou para ler?=Three|Ten|One;;O que Vera fez com o segredo?=Kept it|Told everyone|Wrote it"),
 ex="I couldn't put it down.=Não consegui parar de ler.~Livro bom|It's a real page-turner.=É viciante.~Livro|Don't judge a book by its cover.=Não julgue o livro pela capa.~Provérbio|Let me tell you a secret.=Deixe-me contar um segredo.~Segredo|I wrote it down.=Anotei.~Memória",
 tf="Wrote é passado de write.=T|Spoke é passado de speak.=T|Vera conheceu o autor.=T|Vera contou o segredo.=F",
 odd="read,wrote,spoke,table=table|book,novel,author,fish=fish"),
dict(n=65, gr='didq', vb='happen,arrive,save,call,rescue',
 c1="Did + verbo base|No passado, 'did' carrega o tempo, então o verbo volta à base: 'Did you see it?'. Não diga 'Did you saw?'. O mesmo vale para negativas: 'I didn't go'.",
 c2="Bombeiros|Em inglês, 'firefighter' é o bombeiro (antes, 'fireman'). 'Fire truck' é o caminhão de bombeiros, 'hose' a mangueira, 'ladder' a escada. O número de emergência nos EUA é 911.",
 ar=("The hero of the day","Yesterday a fire started in the old factory near Maple Street. Pete and his team arrived in six minutes. They worked for four hours with long hoses and tall ladders. Nobody got hurt. \"Did you see the flames?\" asked a reporter. \"Yes, I did,\" said Pete. \"They were huge, but my team was fast.\" Today the newspaper has a photo of Pete on the front page. He says, \"We are only doing our job. The real heroes are the people who called for help.\"","Pete e sua equipe controlam um incêndio e aparecem no jornal.","Quanto tempo trabalharam?=Four hours|One hour|All night;;Onde está a foto de Pete?=On the front page|On TV|On the wall"),
 ex="What happened?=O que aconteceu?~Pergunta|It all happened so fast.=Tudo foi muito rápido.~Surpresa|Luckily, nobody was hurt.=Por sorte, ninguém se feriu.~Alívio|I didn't mean to.=Eu não quis.~Desculpa|You did a great job!=Você fez um ótimo trabalho!~Elogio",
 tf="Did you see…? usa o verbo na base.=T|Nobody got hurt.=T|O incêndio foi em uma casa.=F|Pete é bombeiro.=T",
 odd="fire,rescue,hero,bread=bread|did,didn't,does,table=table"),
dict(n=66, gr='conn', vb='go,meet,have,play,watch',
 c1="First, then, after that, finally|Esses conectores organizam o relato. Você pode usar 'first' no início, 'then' ou 'after that' no meio e 'finally' no fim. Soam naturais em histórias orais e escritas.",
 c2="Segunda-feira|Em inglês, 'Monday blues' é o mau humor de segunda. Muitos escritórios têm o hábito de perguntar 'How was your weekend?' logo no início da semana. Sua resposta pode ser curta: 'Great, thanks!'.",
 ar=("Monday stories","On Mondays the neighbors tell stories about their weekend. Lara went to the beach and played volleyball. First she swam, then she had lunch, and after that she played with friends. Finally, she watched the sunset. Ken stayed home and watched old movies. Mia visited her mother and baked bread. Everybody had a different weekend, but everybody was happy to be together again on Monday. \"What about you?\" they asked Pog. Pog smiled and said, \"I just listened to your stories.\"","Os vizinhos contam seus fins de semana diferentes.","Quem assistiu a filmes?=Ken|Lara|Mia;;O que Mia assou?=Bread|Cake|Pizza"),
 ex="How was your weekend?=Como foi seu fim de semana?~Segunda|It was relaxing.=Foi relaxante.~Resposta|I didn't do much.=Não fiz muita coisa.~Resposta|Same old, same old.=A mesma coisa de sempre.~Rotina|Pretty good, thanks.=Bem bom, obrigado.~Resposta",
 tf="First e then são conectores.=T|Lara foi ao shopping.=F|Ken ficou em casa.=T|Mia visitou o pai.=F",
 odd="first,then,after that,table=table|beach,volleyball,sunset,movie=movie"),
dict(n=67, gr='pastreg', vb='travel,visit,stay,fly,take',
 c1="Ago, last e in|'Ago' vem depois do tempo: 'two years ago'. 'Last' vem antes: 'last week'. Para anos, use 'in': 'in 2019'. Eles todos pedem o past simple.",
 c2="Cartões-postais|Antes das redes sociais, viajantes mandavam cartões-postais. Hoje usamos fotos e mensagens, mas em inglês ainda se diz 'Wish you were here!' (Queria que você estivesse aqui).",
 ar=("Photos from Egypt","Two years ago Cleo traveled to Egypt with her sister. They flew for six hours and stayed in a small hotel near the Nile. They visited the great pyramids and a big museum. They rode camels, ate delicious food and bought small souvenirs. A guide told them stories about ancient kings and queens. Cleo took hundreds of photos. Last night she showed them to Kai. \"It was the trip of a lifetime,\" she said. \"I want to go back one day.\"","Cleo viaja ao Egito, visita as pirâmides e guarda centenas de fotos.","Quanto durou o voo?=Six hours|Two hours|Ten hours;;O que eles montaram?=Camels|Horses|Elephants"),
 ex="It was the trip of a lifetime.=Foi a viagem de uma vida.~Viagem|I'm jet-lagged.=Estou com jet lag.~Cansaço|We got lost.=Nos perdemos.~Viagem|Wish you were here!=Queria que você estivesse aqui!~Cartão|Off the beaten track=Fora do roteiro comum~Lugar",
 tf="Ago vem depois da expressão de tempo.=T|Cleo viajou ao Japão.=F|Cleo tirou centenas de fotos.=T|Eles voaram seis horas.=T",
 odd="flight,hotel,pyramids,spoon=spoon|traveled,stayed,visited,go=go"),
dict(n=68, gr='usedto', vb='live,play,walk,eat,change',
 c1="Used to ou usually?|'Used to' fala do passado que não existe mais: 'I used to live in Rio' (hoje não moro). 'Usually' é um hábito do presente: 'I usually walk to work'.",
 c2="Cidades que mudam|Muitas ruas antigas viraram prédios. Em inglês, 'to grow up' é crescer e 'to change' é mudar. 'Back in the day' é uma expressão para falar do passado.",
 ar=("Maple Street 30 years ago","Thirty years ago, Maple Street was a small farm road. There used to be cows and a big barn. People used to walk to the market and children used to play in the fields. Everybody used to know everybody. Now there are houses, a school and a plaza, and many new faces. But some things did not change: neighbors still say hello every morning, and Omar's bakery still smells of fresh bread. \"The world changes,\" says Colin, \"but friendly people stay the same.\"","A rua de hoje era uma estrada de fazenda 30 anos atrás.","O que havia no lugar da praça?=Fields|A hospital|A factory;;O que não mudou?=The neighbors' hello|The barn|The cows"),
 ex="Back in the day…=Antigamente…~Passado|Those were the days.=Que tempos bons.~Nostalgia|Times have changed.=Os tempos mudaram.~Mudança|It's not what it used to be.=Não é mais como era.~Mudança|I grew up there.=Cresci lá.~Infância",
 tf="Used to fala de hábitos passados.=T|Used to é seguido do verbo na base.=T|A rua era uma fazenda.=T|A padaria mudou de dono.=F",
 odd="farm,barn,cows,tablet=tablet|used to,usually,always,red=red"),
dict(n=69, gr='story', vb='find,look,help,give,walk',
 c1="Fábulas de Esopo|As fábulas de Esopo, como 'The Tortoise and the Hare', são lidas há mais de 2.500 anos. Todas terminam com uma moral. Em inglês: 'The moral of the story is…'.",
 c2="Marcadores de história|'Once upon a time' (era uma vez), 'one day' (um dia), 'suddenly' (de repente), 'finally' (finalmente) e 'happily ever after' (felizes para sempre) são marcadores que organizam qualquer história.",
 ar=("The honest fox","Once upon a time there was a small fox. She was hungry, so she looked for food in the forest. Suddenly she found a basket of berries, but a note said: 'For Anna.' The fox was very hungry, but she did not eat them. When Anna arrived, she saw the fox sitting next to the basket. \"You didn't eat my berries,\" said Anna. \"They aren't mine,\" said the fox. Anna smiled and gave the fox some berries as a thank you. The moral is: honesty is always rewarded.","Uma raposa esfomeada não come as frutas alheias e é recompensada.","O que dizia o bilhete?=For Anna|For Fox|For Mia;;Qual é a moral?=Honesty is rewarded|Be fast|Be rich"),
 ex="Happily ever after=Felizes para sempre~Final de conto|Long story short…=Resumindo…~Contar|To make a long story short=Para resumir~Contar|The moral of the story=A moral da história~Fábula|Once upon a time=Era uma vez~Início",
 tf="Once upon a time começa muitos contos.=T|Suddenly significa de repente.=T|A raposa comeu as frutas.=F|Anna deu frutas à raposa.=T",
 odd="once,suddenly,finally,table=table|fox,bear,wolf,basket=basket"),
dict(n=70, gr='didq', vb='go,have,see,tell,remember',
 c1="Memórias em inglês|'Remember' é lembrar e 'forget' é esquecer. 'I remember going there' (lembro de ter ido) e 'Remember to call me' (lembre de me ligar) têm sentidos diferentes.",
 c2="Contar histórias|Em inglês, boas histórias têm 3 elementos: 'character' (personagem), 'setting' (cenário) e 'plot' (enredo). Seu cérebro lembra 22 vezes mais de fatos contados em forma de história.",
 ar=("An evening of memories","At the memory night, everybody shares a story. Kate talks about her trip to Japan and the sushi she ate every day. Eva talks about her childhood on a farm with hens and a dog. Mia tells a funny story about a lost cat that came home alone. Nobody looks at the clock. When the stories end, it is midnight, and the neighbors say, \"Let's do it again!\" On the way home, Eva says, \"Memories are the best gifts. You give them and you keep them.\"","Uma noite de memórias reúne os vizinhos até a meia-noite.","Sobre o que Mia conta?=A lost cat|A trip|A farm;;Que horas terminam?=Midnight|Noon|Six"),
 ex="Let's reminisce.=Vamos relembrar.~Nostalgia|It brings back memories.=Traz lembranças.~Nostalgia|I'll never forget it.=Nunca vou esquecer.~Memória|Do you remember when…?=Você se lembra de quando…?~Memória|It rings a bell.=Isso me lembra algo.~Lembrar vagamente",
 tf="Remember é lembrar.=T|Kate falou sobre o Egito.=F|Eva viveu em uma fazenda.=T|Terminaram ao meio-dia.=F",
 odd="remember,forget,recall,table=table|trip,farm,cat,Monday=Monday"),
]
